<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { useRoute, useRouter } from 'vue-router'
import PotreeFrame from '@/components/PotreeFrame.vue'
import { getStudentTask, getStudentWorkspace, saveStudentDraft, submitStudentTask } from '@/api/student'
import type { StudentTask, StudentWorkspace } from '@/types/student'
import type { Point3D } from '@/types/viewer'

const route=useRoute(),router=useRouter(),frame=ref<InstanceType<typeof PotreeFrame>>(),task=ref<StudentTask>(),workspace=ref<StudentWorkspace>(),loading=ref(true),viewerError=ref(''),point=ref<Point3D>({x:0,y:0,z:0}),title=ref(''),description=ref(''),saveState=ref('已保存'),timer=ref<number>(),mock=import.meta.env.VITE_USE_MOCK!=='false'
const taskId=()=>String(route.params.taskId)
const readonly=computed(()=>Boolean(workspace.value?.submitted||task.value?.status==='NOT_STARTED'||(task.value?.status==='EXPIRED'&&!task.value.allowLate)))
const forcedMasks=computed(()=>workspace.value?.forcedDesensitizationRules.filter(rule=>rule.mode==='HIDE').map(rule=>({id:rule.id,type:'HIDE' as const,title:rule.title,range:{min:rule.geometry.min,max:rule.geometry.max},enforced:true}))||[])
async function load(){loading.value=true;try{const[t,w]=await Promise.all([getStudentTask(taskId()),getStudentWorkspace(taskId())]);task.value=t;workspace.value=w}catch(e){viewerError.value=e instanceof Error?e.message:'实训工作台加载失败'}finally{loading.value=false}}
function schedule(){if(readonly.value||!workspace.value)return;saveState.value='待保存';if(timer.value)window.clearTimeout(timer.value);timer.value=window.setTimeout(save,900)}
async function save(){if(!workspace.value||readonly.value)return false;saveState.value='保存中…';try{workspace.value=await saveStudentDraft(taskId(),workspace.value);saveState.value='已保存';return true}catch(e){saveState.value='保存失败';ElMessage.error((e as {response?:{status?:number}}).response?.status===409?'当前任务状态不允许保存，请刷新后重试。':'草稿自动保存失败');return false}}
function addPoint(){if(!workspace.value||!title.value.trim())return ElMessage.warning('请输入标记标题');workspace.value.annotations.unshift({id:`local-${Date.now()}`,type:'POINT_MARK',geometry:{position:point.value},title:title.value,description:description.value,createdAt:new Date().toISOString()});title.value='';description.value='';schedule()}
async function submit(){if(!workspace.value||readonly.value||!await save())return;try{const value=await submitStudentTask(taskId(),workspace.value);workspace.value.submitted=true;workspace.value.submittedAt=value.submittedAt;workspace.value.submissionVersion=value.version;task.value&&(task.value.status='SUBMITTED');ElMessage.success('实训已提交')}catch(e){ElMessage.error((e as {response?:{status?:number}}).response?.status===409?'当前任务状态不允许提交，请刷新后重试。':'提交失败')}}
onMounted(load)
</script>
<template><main class="workspace"><header><div><p>学生 / 实训工作台</p><h1>{{task?.name||'实训工作台'}}</h1></div><el-button @click="router.push('/student/tasks')">返回任务</el-button></header><el-alert v-if="viewerError" title="无法加载实训工作台" :description="viewerError" type="error" :closable="false" show-icon/><el-skeleton v-else-if="loading" :rows="12" animated/><section v-else-if="workspace" class="layout"><div class="viewer"><PotreeFrame ref="frame" :manifest-url="workspace.manifestUrl" :mock="mock" :masks="forcedMasks" :hide-preview="true" @error="viewerError=$event" @pick="point=$event"/></div><aside><el-alert v-if="forcedMasks.length" title="教学强制遮挡已生效" description="敏感区域由教学版本强制控制，学生不能关闭、编辑或删除。" type="warning" :closable="false"/><el-tabs><el-tab-pane label="实训工具"><el-button-group><el-button :disabled="readonly" @click="frame?.startPointPick()">取点</el-button><el-button :disabled="readonly" @click="frame?.startArea()">重点区域</el-button><el-button :disabled="readonly" @click="frame?.startMeasurement()">两点测距</el-button><el-button @click="frame?.resetView()">复位</el-button></el-button-group><el-divider>点位标记</el-divider><el-input v-model="title" :disabled="readonly" placeholder="标记标题"/><el-input v-model="description" :disabled="readonly" type="textarea" placeholder="描述"/><el-button type="primary" :disabled="readonly" @click="addPoint">加入草稿</el-button></el-tab-pane><el-tab-pane label="笔录"><el-form label-position="top"><el-form-item label="现场概况"><el-input v-model="workspace.draft.overview" :disabled="readonly" type="textarea" @input="schedule"/></el-form-item><el-form-item label="勘验过程"><el-input v-model="workspace.draft.process" :disabled="readonly" type="textarea" @input="schedule"/></el-form-item><el-form-item label="物证描述"><el-input v-model="workspace.draft.evidenceDescription" :disabled="readonly" type="textarea" @input="schedule"/></el-form-item><el-form-item label="初步结论"><el-input v-model="workspace.draft.preliminaryConclusion" :disabled="readonly" type="textarea" @input="schedule"/></el-form-item></el-form></el-tab-pane></el-tabs><footer>自动保存：{{saveState}} <el-button v-if="!readonly" type="primary" @click="submit">提交实训</el-button></footer></aside></section></main></template>
<style scoped>.workspace{height:100vh;background:#f4f7fb}.workspace>header{height:76px;padding:14px 24px;display:flex;justify-content:space-between;align-items:center;background:#fff}.workspace p{margin:0;color:#64748b;font-size:12px}h1{margin:5px 0;font-size:20px}.layout{display:grid;grid-template-columns:minmax(0,1fr) 400px;height:calc(100vh - 76px)}aside{overflow:auto;padding:16px;background:#fff;border-left:1px solid #dde4ee}footer{margin-top:20px}@media(max-width:1100px){.layout{grid-template-columns:1fr}.viewer{height:55vh}}</style>
